type StageSpec = {
  width: number; height: number; theme: Theme; water?: boolean; boss?: boolean;
  columns?: number; startX?: number; startY?: number; startFacing?: number; seed: number; name: string; sky: string; bossName?: string;
  platforms: number[][];
  pits?: number[][];
  blocks?: number[][];
};

function makeOriginalStage(stageNo: number, spec: StageSpec): G {
  const screens = ORIGINAL_SCREENS[stageNo] || [];
  const columns = spec.columns || Math.ceil(spec.width / 16);
  const rows = Math.max(Math.ceil(screens.length / columns), Math.ceil(spec.height / 12));
  const g = grid(columns * 16, rows * 12);

  const token = (id: number) => {
    if (id === 0 || id === 0x0a || id === 0x0b || id === 0x0c || id === 0x20 || id === 0x21) return ".";
    if (id >= 0x50 && id <= 0x57) return "#";
    if (id === 0x01) return "K";
    if (id === 0x02) return "Q";
    if (id === 0x03) return "S";
    return "R";
  };

  screens.forEach((hex, index) => {
    const data = decodeLevelScreen(hex);
    const screenX = index % columns;
    const screenY = Math.floor(index / columns);
    for (let y = 0; y < 12; y++) {
      for (let x = 0; x < 16; x++) put(g, screenX * 16 + x, screenY * 12 + y, token(data[y * 16 + x] || 0));
    }
  });

  const startX = spec.startX === undefined ? 2 : spec.startX;
  const startY = spec.startY === undefined ? (spec.water ? 5 : g.length - 3) : spec.startY;
  fill(g, Math.max(0, startX - 1), Math.min(g[0].length - 1, startX + 1), Math.max(0, startY - 1), startY, ".");
  put(g, startX, startY, "P");
  if (stageNo === 11) fill(g, startX - 1, startX + 1, startY + 1, startY + 1, "#");

  let hasExit = false;
  let hasBoss = false;
  (ORIGINAL_ENTITIES[stageNo] || []).forEach(([screen, x, y, entity]) => {
    const screenX = screen % columns;
    const screenY = Math.floor(screen / columns);
    const tx = screenX * 16 + Math.floor(x / 16);
    const ty = screenY * 12 + Math.floor(y / 16);
    if (entity === "F" || entity === "B") fill(g, Math.max(0, tx - 1), Math.min(g[0].length - 1, tx + 1), Math.max(0, ty - 1), Math.min(g.length - 1, ty + 1), ".");
    put(g, tx, ty, entity);
    if (entity === "F") hasExit = true;
    if (entity === "B") hasBoss = true;
  });

  if (!hasExit && !hasBoss) put(g, g[0].length - 3, g.length - 3, "F");
  return g;
}

function makeStage(s: StageSpec): G {
  const g = grid(s.width, s.height);
  const floor = s.height - 2;
  const startY = s.startY ?? (s.water ? Math.max(3, Math.floor(s.height / 2)) : floor - 1);
  put(g, 2, startY, "P");

  if (s.water) {
    // Open swimming routes with staggered rock shelves and clear channels.
    fill(g, 0, s.width - 1, s.height - 1, s.height - 1, "R");
    for (let x = 0; x < s.width; x += 16) {
      const y = 2 + ((x * 3 + s.seed * 5) % Math.max(5, s.height - 6));
      fill(g, x + 5, Math.min(s.width - 2, x + 8), y, y, "R");
      if (x % 32 === 0) put(g, Math.min(s.width - 2, x + 11), Math.min(s.height - 3, y + 3), "S");
      put(g, Math.min(s.width - 2, x + 13), Math.max(1, y - 1), "p");
      if (x % 3 === 0) put(g, Math.min(s.width - 2, x + 2), Math.max(1, y - 3), "$");
    }
    s.platforms.forEach(([x, y, len]) => {
      fill(g, x, Math.min(s.width - 2, x + len - 1), y, y, "R");
      if (len > 3) put(g, Math.min(s.width - 2, x + Math.floor(len / 2)), Math.max(1, y - 2), "$");
    });
    (s.blocks || []).forEach(([x, y]) => put(g, x, y, "R"));
    for (let x = 14; x < s.width - 8; x += 29) put(g, x, 2 + ((x + s.seed) % Math.max(5, s.height - 5)), "p");
  } else {
    fill(g, 0, s.width - 1, floor, s.height - 1, "#");
    (s.pits || []).forEach(([x0, x1]) => fill(g, x0, x1, floor, s.height - 1, "."));
    // Short, climbable ledges are deliberately varied by stage.
    s.platforms.forEach(([x, y, len, type = 0]) => {
      fill(g, x, Math.min(s.width - 2, x + len - 1), y, y, type === 1 ? "R" : "S");
      if (len > 3 && type !== 2) put(g, Math.min(s.width - 2, x + Math.floor(len / 2)), y - 1, type === 1 ? "Q" : "$");
    });
    for (let x = 15; x < s.width - 10; x += 23) {
      const y = s.name.startsWith("2 ") ? floor - 1 : floor - 1 - ((Math.floor(x / 23) + s.seed) % 3);
      put(g, x, y, (Math.floor(x / 23) + s.seed) % 4 === 0 ? "v" : "w");
      if (x % 2) put(g, x + 4, y - 2, "$");
    }
    (s.blocks || []).forEach(([x, y, type]) => put(g, x, y, type === 1 ? "Q" : type === 2 ? "K" : "S"));
  }

  // Every stage has its own endpoint and boss arena marker.
  const endX = s.width - 5;
  if (s.boss) put(g, endX - 5, floor - 1, "B");
  else put(g, endX, s.water ? Math.max(2, startY) : floor - 1, "F");
  return g;
}

